function getLastWorkdayDate(daysBack = 1) {
  const today = new Date();
  const date = new Date(today);
  date.setDate(today.getDate() - daysBack);
  console.log(`[DEBUG] \u5DE5\u4F5C\u65E5\u8BA1\u7B97 - \u5F00\u59CB\u65E5\u671F: ${date.toISOString().split("T")[0]} (${getWeekdayName(date.getDay())})`);
  let iterations = 0;
  while (date.getDay() === 0 || date.getDay() === 6) {
    date.setDate(date.getDate() - 1);
    iterations++;
    console.log(`[DEBUG] \u5DE5\u4F5C\u65E5\u8BA1\u7B97 - \u8DF3\u8FC7\u5468\u672B\uFF0C\u56DE\u9000\u5230: ${date.toISOString().split("T")[0]} (${getWeekdayName(date.getDay())})`);
    if (iterations > 7) {
      console.error(`[DEBUG] \u5DE5\u4F5C\u65E5\u8BA1\u7B97 - \u5F02\u5E38\uFF1A\u56DE\u9000\u8D85\u8FC77\u5929`);
      break;
    }
  }
  const year = date.getFullYear();
  const month = (date.getMonth() + 1).toString().padStart(2, "0");
  const day = date.getDate().toString().padStart(2, "0");
  const result = `${year}-${month}-${day}`;
  console.log(`[DEBUG] \u5DE5\u4F5C\u65E5\u8BA1\u7B97 - \u6700\u7EC8\u7ED3\u679C: ${result} (${getWeekdayName(date.getDay())})`);
  return result;
}
function getWeekdayName(dayOfWeek) {
  const weekdays = ["\u5468\u65E5", "\u5468\u4E00", "\u5468\u4E8C", "\u5468\u4E09", "\u5468\u56DB", "\u5468\u4E94", "\u5468\u516D"];
  return weekdays[dayOfWeek] || "\u672A\u77E5";
}

