function analyzeTaskCompletion(taskContent) {
  const result = {
    totalTasks: 0,
    completedTasks: 0,
    unfinishedTasksList: []
  };
  if (!taskContent) {
    console.log(`[DEBUG] \u4EFB\u52A1\u5206\u6790 - \u5185\u5BB9\u4E3A\u7A7A`);
    return result;
  }
  console.log(`[DEBUG] \u4EFB\u52A1\u5206\u6790 - \u5F00\u59CB\u5206\u6790\u5185\u5BB9\uFF0C\u957F\u5EA6: ${taskContent.length}`);
  console.log(`[DEBUG] \u4EFB\u52A1\u5206\u6790 - \u5185\u5BB9\u9884\u89C8:
${taskContent}`);
  const allTasksRegex = /^[\s]*-[\s]*\[([ xX✓])\][\s]+(.+)$/gm;
  const completedTasksRegex = /^[\s]*-[\s]*\[([xX✓])\][\s]+(.+)$/gm;
  const unfinishedTasksRegex = /^[\s]*-[\s]*\[[\s]\][\s]+(.+)$/gm;
  const allTasksMatches = [...taskContent.matchAll(allTasksRegex)];
  result.totalTasks = allTasksMatches.length;
  const completedTasksMatches = [...taskContent.matchAll(completedTasksRegex)];
  result.completedTasks = completedTasksMatches.length;
  const unfinishedTasksMatches = [...taskContent.matchAll(unfinishedTasksRegex)];
  result.unfinishedTasksList = unfinishedTasksMatches.map((match) => {
    let taskText = match[1].trim();
    taskText = taskText.replace(/\s*✅\s*\d{4}-\d{2}-\d{2}.*$/, "");
    return taskText;
  });
  console.log(`[DEBUG] \u4EFB\u52A1\u5206\u6790\u7ED3\u679C:`);
  console.log(`  - \u603B\u4EFB\u52A1\u5339\u914D: ${allTasksMatches.length}`);
  console.log(`  - \u5DF2\u5B8C\u6210\u5339\u914D: ${completedTasksMatches.length}`);
  console.log(`  - \u672A\u5B8C\u6210\u5339\u914D: ${unfinishedTasksMatches.length}`);
  console.log(`  - \u672A\u5B8C\u6210\u4EFB\u52A1\u5217\u8868: ${result.unfinishedTasksList.slice(0, 3).join(", ")}${result.unfinishedTasksList.length > 3 ? "..." : ""}`);
  const taskLines = taskContent.split("\n").filter((line) => line.includes("- ["));
  console.log(`[DEBUG] \u627E\u5230\u7684\u4EFB\u52A1\u884C\u793A\u4F8B (\u5171${taskLines.length}\u884C):`);
  taskLines.slice(0, 10).forEach((line, index) => {
    console.log(`  ${index + 1}. "${line}"`);
  });
  if (taskLines.length === 0) {
    console.log(`[DEBUG] \u672A\u627E\u5230\u4EFB\u52A1\u884C\uFF0C\u8F93\u51FA\u6240\u6709\u5185\u5BB9\u884C:`);
    const allLines = taskContent.split("\n");
    allLines.slice(0, 20).forEach((line, index) => {
      console.log(`  ${index + 1}. "${line}"`);
    });
  }
  return result;
}
function generateStatisticsContent(tasks, t, maxSuggestions = 5) {
  let totalTasks;
  let completedTasks;
  let unfinishedTasks = [];
  if (Array.isArray(tasks)) {
    totalTasks = tasks.length;
    completedTasks = tasks.filter((task) => task.isCompleted).length;
    unfinishedTasks = tasks.filter((task) => !task.isCompleted).map((task) => ({ task: task.task }));
  } else {
    totalTasks = tasks.totalTasks;
    completedTasks = tasks.completedTasks;
    unfinishedTasks = tasks.unfinishedTasksList.map((task) => ({ task }));
  }
  const completionRate = totalTasks > 0 ? Math.round(completedTasks / totalTasks * 100) : 0;
  const displayTasks = unfinishedTasks.slice(0, maxSuggestions);
  let content = `## ${t("statistics.title")}
---
`;
  content += `- ${t("statistics.totalTasks")}: ${totalTasks}
`;
  content += `- ${t("statistics.completedTasks")}: ${completedTasks}
`;
  content += `- ${t("statistics.completionRate")}: ${completionRate}%

`;
  if (unfinishedTasks.length > 0) {
    content += `### ${t("statistics.suggestions")}
---
`;
    displayTasks.forEach((item) => {
      content += `- [ ] ${item.task}
`;
    });
    if (unfinishedTasks.length > maxSuggestions) {
      const remaining = unfinishedTasks.length - maxSuggestions;
      const moreTasks = remaining === 1 ? t("statistics.moreTasks.singular") : `${remaining} ${t("statistics.moreTasks.plural")}`;
      content += `- *${moreTasks}*
`;
    }
  }
  return content;
}
async function readDailyTaskFile(vault, filePath) {
  try {
    const abstractFile = vault.getAbstractFileByPath(filePath);
    if (!abstractFile || !(abstractFile instanceof import_obsidian.TFile)) {
      return null;
    }
    const content = await vault.read(abstractFile);
    return content;
  } catch (error) {
    console.error(`Error reading daily task file: ${filePath}`, error);
    return null;
  }
}

